window.products.push({"id":931544,"name":"Whirlpool WRS965CIAM 24.5 Cu. Ft. Stainless Steel Counter Depth Side-By-Side Refrigerator - Energy Star","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61kYu2Az1rL._AC_SL1290_.jpg","description":"Whirlpool Gold ® 25 cu. ft. Counter Depth Side-by-Side Refrigerator with the MicroEdge shelves. Stock up on all your favorite fresh and frozen foods with the Whirlpool ® 25 cu. ft. counter depth side-by-side refrigerator. The industry-exclusive MicroEdge shelves offer 25% more usable shelf space and help contain leaks. The In-Door-Ice ® Plus ice dispensing system also creates 30% more usable space in the freezer and includes a removable ice bin. It tilts out and can be placed on the counter to make filling glasses, pitchers and coolers easy. This model also delivers efficient cooling performance using built-in sensors to measure internal temperature and activate the compressor only when necessary.","images":["https://m.media-amazon.com/images/I/61kYu2Az1rL._AC_SL1290_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Whirlpool","source_asin":"B008KTHEUW","category_path":"Home & Kitchen"},"sku":"BM-931544","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B008KTHEUW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B008KTHEUW","price_pending":true,"merchant_ready":false});
